/* src/css/style.css */
body {
  margin: 0;
  font-family: Arial, sans-serif;
}

main {
  height: 1000px;
  padding: 16px;
  box-sizing: border-box;
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 80px;
  padding: 0 24px;
  box-sizing: border-box;
  background-color: #222222;
  color: #1ba94c;
}

/* <a> does not inherit the parent's color by default */
.footer a,
.footer .back-to-top {
  color: #1ba94c;
  text-decoration: none;
}

.footer .social-icons {
  display: flex;
  gap: 16px;
}

.footer .social-icons i {
  font-size: 24px;
  color: #1ba94c;
}
